const MusicVisualizer = ({ tempo, mood, songTitle, artistRef }) => {
  const sketchRef = useRef();

  useEffect(() => {
    const sketch = (p) => {
      let particles = [];
      const colors = MOOD_COLORS[mood] || MOOD_COLORS.Default;
      const beatTime = (60 / tempo) * 1000; // Beat duration in milliseconds
      let lastBeat = 0;
      let beatSize = 1;

      class Particle {
        pos: any;
        vel: any;
        acc: any;
        maxSpeed: number;
        color: any;

        constructor() {
          this.pos = p.createVector(p.random(p.width), p.random(p.height));
          this.vel = p.createVector(p.random(-1, 1), p.random(-1, 1));
          this.acc = p.createVector(0, 0);
          this.maxSpeed = 2;
          this.color = p.color(p.random(colors));
        }

        update() {
          this.vel.add(this.acc);
          this.vel.limit(this.maxSpeed);
          this.pos.add(this.vel);
          this.acc.mult(0);
        }

        edges() {
          if (this.pos.x > p.width) this.pos.x = 0;
          if (this.pos.x < 0) this.pos.x = p.width;
          if (this.pos.y > p.height) this.pos.y = 0;
          if (this.pos.y < 0) this.pos.y = p.height;
        }

        display() {
          p.noStroke();
          p.fill(this.color);
          p.ellipse(this.pos.x, this.pos.y, 4, 4);
        }
      }

      p.setup = () => {
        const container = sketchRef.current;
        p.createCanvas(container.offsetWidth, 400).parent(sketchRef.current);
        for (let i = 0; i < 100; i++) {
          particles.push(new Particle());
        }
      };

      p.draw = () => {
        p.background(18, 18, 18, 50); // Fading background

        p.textAlign(p.CENTER, p.CENTER);
        p.fill(255, 255, 255, 100); 
        p.textSize(28);
        p.text(songTitle || 'Untitled Song', p.width / 2, p.height / 2 - 20);
        p.textSize(18);
        p.fill(255, 255, 255, 80);
        p.text(artistRef || 'Independent Artist', p.width / 2, p.height / 2 + 20);

        const currentTime = p.millis();
        if (currentTime - lastBeat > beatTime) {
            lastBeat = currentTime;
            beatSize = 1.5;
        }
        beatSize = p.lerp(beatSize, 1, 0.1); 

        const orbSize = p.width / 4 * beatSize;
        const mainColor = p.color(colors[0]);
        mainColor.setAlpha(150);
        p.fill(mainColor);
        p.noStroke();
        p.ellipse(p.width / 2, p.height / 2, orbSize, orbSize);

        for (let particle of particles) {
          particle.update();
          particle.edges();
          particle.display();
        }
      };

      p.windowResized = () => {
          const container = sketchRef.current;
          if(container) {
             p.resizeCanvas(container.offsetWidth, 400);
          }
      };
    };

    let p5Instance = new p5(sketch, sketchRef.current);

    return () => {
      p5Instance.remove();
    };
  }, [tempo, mood, songTitle, artistRef]);

  return <div ref={sketchRef} className="visualizer-canvas"></div>;
};


const App = () => {
  const [genreOptions, setGenreOptions] = useState(INITIAL_GENRE_OPTIONS);
  const [subgenreOptions, setSubgenreOptions] = useState(INITIAL_SUBGENRE_OPTIONS);
  const [worldMusicOptions, setWorldMusicOptions] = useState(INITIAL_WORLD_MUSIC_OPTIONS);
  const [moodOptions, setMoodOptions] = useState(MOOD_OPTIONS);
  const [themeOptions, setThemeOptions] = useState(THEME_OPTIONS);

  const [genre, setGenre] = useState(genreOptions[0]);
  const [subgenre, setSubgenre] = useState(subgenreOptions[0]);
  const [worldMusic, setWorldMusic] = useState(worldMusicOptions[0]);
  const [mood, setMood] = useState(moodOptions[0]);
  const [theme, setTheme] = useState(themeOptions[0]);
  const [lyricLanguage, setLyricLanguage] = useState(LYRIC_LANGUAGE_OPTIONS[0]);
  const [duration, setDuration] = useState("4");
  const [songTitle, setSongTitle] = useState("");
  const [artistRef, setArtistRef] = useState("");
  const [tempo, setTempo] = useState(120);
  const [key, setKey] = useState(KEY_OPTIONS[0]);
  const [timeSignature, setTimeSignature] = useState(TIME_SIGNATURE_OPTIONS[0]);
  const [numberOfImages, setNumberOfImages] = useState(4);
  const [backgroundTrack, setBackgroundTrack] = useState(null);
  const [backgroundTrackUrl, setBackgroundTrackUrl] = useState(null);

  const [loading, setLoading] = useState(false);
  const [assistantLoading, setAssistantLoading] = useState(false);
  const [error, setError] = useState(null);
  const [outputBlocks, setOutputBlocks] = useState([]);
  const [sources, setSources] = useState([]); 
  const [imageLoading, setImageLoading] = useState(false);
  const [generatedImages, setGeneratedImages] = useState([]);
  const [imageError, setImageError] = useState(null);

  const backgroundTrackUrlRef = useRef(backgroundTrackUrl);
  backgroundTrackUrlRef.current = backgroundTrackUrl;


  useEffect(() => {
    return () => {
      if (backgroundTrackUrlRef.current) {
        URL.revokeObjectURL(backgroundTrackUrlRef.current);
      }
    };
  }, []);

  const handleAssistantClick = async () => {
    setAssistantLoading(true);
    setError(null);
    try {
      let prompt = "";
      const isSpecificSong = songTitle.trim().length > 0 && artistRef.trim().length > 0;
      let requestConfig = {};

      if (isSpecificSong) {
         requestConfig = {
             tools: [{ googleSearch: {} }]
         };
         prompt = `Act as a Music Intelligence Agent.
Target Request: Song "${songTitle}", Artist Reference "${artistRef}".

**ANALYSIS LOGIC:**
1. **OFFICIAL CHECK:** Check if "${songTitle}" is an existing song officially released by "${artistRef}".
2. **ORIGINAL SEARCH:** Find the ORIGINAL artist of "${songTitle}". Parse title for artist names (e.g. "Rhoma Irama").
3. **METADATA RETRIEVAL:** Find BPM, Key, Genre of the ORIGINAL version and suggest parameters for a version in the style of "${artistRef}".

Return ONLY valid JSON:
{
  "genre": "...", "subgenre": "...", "worldMusic": "...", "mood": "...", "theme": "...", "tempo": Number, "key": "...", "timeSignature": "...", "lyricLanguage": "...", "durationMinutes": Number
}`;

      } else {
         requestConfig = {
           responseMimeType: "application/json",
           responseSchema: {
             type: Type.OBJECT,
             properties: {
               genre: { type: Type.STRING },
               subgenre: { type: Type.STRING },
               worldMusic: { type: Type.STRING },
               mood: { type: Type.STRING },
               theme: { type: Type.STRING },
               tempo: { type: Type.NUMBER },
               key: { type: Type.STRING },
               timeSignature: { type: Type.STRING },
               lyricLanguage: { type: Type.STRING },
               durationMinutes: { type: Type.NUMBER },
             },
           },
         };

         prompt = `Suggest parameters for a new hit song. Genre/Subgenre/WorldMusic/Mood/Theme/Tempo/Key/TimeSignature/Language/Duration. Style: ${artistRef || 'General'}.`;
      }

      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: requestConfig,
      }));

      let suggestions;
      if (isSpecificSong) {
          let text = response.text || "";
          text = text.replace(/```json/g, "").replace(/```/g, "");
          const firstOpen = text.indexOf('{');
          const lastClose = text.lastIndexOf('}');
          if (firstOpen !== -1 && lastClose !== -1) {
              suggestions = JSON.parse(text.substring(firstOpen, lastClose + 1));
          } else {
             throw new Error("Could not retrieve specific song data.");
          }
      } else {
          suggestions = JSON.parse(response.text);
      }

      if (suggestions.genre) {
          setGenreOptions(prev => !prev.includes(suggestions.genre) ? [suggestions.genre, ...prev] : prev);
          setGenre(suggestions.genre);
      }
      if (suggestions.subgenre) {
          setSubgenreOptions(prev => !prev.includes(suggestions.subgenre) ? [suggestions.subgenre, ...prev] : prev);
          setSubgenre(suggestions.subgenre);
      }
      if (suggestions.worldMusic) {
          setWorldMusicOptions(prev => !prev.includes(suggestions.worldMusic) ? [suggestions.worldMusic, ...prev] : prev);
          setWorldMusic(suggestions.worldMusic);
      }
      if (suggestions.mood) {
          setMoodOptions(prev => !prev.includes(suggestions.mood) ? [suggestions.mood, ...prev] : prev);
          setMood(suggestions.mood);
      }
      if (suggestions.theme) {
          setThemeOptions(prev => !prev.includes(suggestions.theme) ? [suggestions.theme, ...prev] : prev);
          setTheme(suggestions.theme);
      }
      if (suggestions.tempo) setTempo(Math.round(Math.max(40, Math.min(220, suggestions.tempo))));
      if (suggestions.key) {
           const match = KEY_OPTIONS.find(k => suggestions.key.startsWith(k));
           if(match) setKey(match);
      }
      if (suggestions.timeSignature && TIME_SIGNATURE_OPTIONS.includes(suggestions.timeSignature)) setTimeSignature(suggestions.timeSignature);
      if (suggestions.lyricLanguage) {
        if (suggestions.lyricLanguage.toLowerCase().includes('indonesia')) setLyricLanguage('Indonesian');
        else if (suggestions.lyricLanguage.toLowerCase().includes('english')) setLyricLanguage('English');
      }
      if (suggestions.durationMinutes) setDuration(suggestions.durationMinutes >= 6 ? "8" : "4");

    } catch (e) {
      setError("AI assistant failed. Please try again.");
    } finally {
      setAssistantLoading(false);
    }
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setOutputBlocks([]);
    setGeneratedImages([]);
    setSources([]);

    const maxTokens = 8192;
    const isSpecificSong = songTitle.trim().length > 0 && artistRef.trim().length > 0;

    const promptContext = isSpecificSong
      ? `Act as a Professional Music Transcriber and Producer. 
      Target: "${songTitle}" in the style of "${artistRef}".

      **CRITICAL SEARCH TASK:**
      1. Use Google Search to find the **ORIGINAL ARTIST** and **100% ORIGINAL VERBATIM LYRICS** for "${songTitle}". 
      2. If the user input contains the original artist's name (e.g. "Rhoma Irama"), prioritize that source.
      3. **DO NOT SUMMARIZE.** Do not use placeholders like "(repeat chorus)".
      4. **VERBATIM RULE:** You MUST output every single line of the original lyrics. If you don't find it, search deeper.

      **PRODUCTION TASK:**
      1. Keep the lyrics and chord progression ORIGINAL.
      2. Re-arrange the instrumentation, production notes, and vocal performance to match the style of "${artistRef}".
      3. If duration is set to 8 min, include extended instrumental sections (solos, atmosphere) but do NOT shorten the lyrics.

      **FORMATTING:**
      - All chords in [Square Brackets] ABOVE lyrics.
      - Sections formatted as: [Section, Time, BPM, Vibe | Instr: ..., | Prod: ..., | Perf: ...]
      - Intro/Outro included.
      `
      : `Act as a Songwriter and Producer. Create an original song based on provided parameters.`;

    const fullTemplate = `[title: ${songTitle || 'Untitled'}]
[artist: ${artistRef || 'Unknown Artist'}]
[genre: ${genre}]
[subgenre: ${subgenre}]
[world music influence: ${worldMusic}]
[tempo: ${tempo} BPM]
[key: ${key}]
[time signature: ${timeSignature}]
[lyric language: ${lyricLanguage}]
[duration: ${duration === "4" ? "~4 min" : "~8 min"}]
[mood: ${mood}]
[theme: ${theme}]

[Song Composition]
(Generate full structure here)

[STYLE_DESCRIPTION_SECTION]
(Write a detailed sonic summary here, under 1000 chars, focus on textures and dynamics, no artist names.)
`;

    const prompt = `${promptContext}

    Using the provided template, generate the output. 
    IF this is an existing song, you MUST provide 100% original, verbatim lyrics.
    TOTAL OUTPUT MUST BE UNDER 7000 CHARACTERS to accommodate full lyrics.

    ---
    ${fullTemplate}
    ---
    `;

    const generateConfig: any = {
      maxOutputTokens: maxTokens,
      thinkingConfig: { thinkingBudget: 1024 },
    };

    if (isSpecificSong) {
      generateConfig.tools = [{googleSearch: {}}];
    }

    try {
      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: generateConfig,
      }));

      const responseText = response.text.trim();

      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
          const chunks = response.candidates[0].groundingMetadata.groundingChunks;
          const uniqueSources = chunks
              .map((chunk: any) => chunk.web?.uri)
              .filter((uri: string) => uri)
              .filter((value: string, index: number, self: string[]) => self.indexOf(value) === index);
          setSources(uniqueSources);
      }

      const summaryMarker = '[STYLE_DESCRIPTION_SECTION]';
      const summaryIndex = responseText.lastIndexOf(summaryMarker);

      if (summaryIndex !== -1) {
        const templateResult = responseText.substring(0, summaryIndex).trim();
        let summaryResult = responseText.substring(summaryIndex + summaryMarker.length).trim();
        if (summaryResult.startsWith(':')) summaryResult = summaryResult.substring(1).trim();

        setOutputBlocks([
          { title: "Generated Music Template", content: templateResult },
          { title: "Style Description", content: summaryResult },
        ]);
      } else if (responseText) {
        setOutputBlocks([
          { title: "Generated Music Template", content: responseText },
          { title: "Style Description", content: "Not generated properly." },
        ]);
      } else {
        setError("The AI generated an empty response.");
      }
    } catch (e) {
      setError("Failed to generate template. Quota or rate limit likely hit.");
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateImages = async () => {
    setImageLoading(true);
    setImageError(null);
    setGeneratedImages([]);

    try {
      let songDescription = `A visual representation of a song with the mood '${mood}' and theme '${theme}'.`; 
      if (outputBlocks.length > 0) {
        const summaryBlock = outputBlocks.find(b => b.title === "Style Description");
        if (summaryBlock) songDescription = summaryBlock.content;
      }

      const imagePrompt = `Dynamic, cinematic action shot of a band performing "${songTitle}" in the style of "${artistRef}". Genre: ${genre}, Mood: ${mood}. Visual Style: ${songDescription}`;

      const response = await callWithRetry(() => ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: imagePrompt,
        config: {
          numberOfImages: numberOfImages,
          outputMimeType: 'image/jpeg',
          aspectRatio: '16:9',
        },
      }), 3, 5000);

      const imageUrls = response.generatedImages.map(img => `data:image/jpeg;base64,${img.image.imageBytes}`);
      setGeneratedImages(imageUrls);

    } catch (e) {
      setImageError("Image generation failed. Rate limits may apply.");
    } finally {
      setImageLoading(false);
    }
  };

  return (
    <div className="container">
      <header>
        <h1>Warga Digital Studio</h1>
        <div className="promo-banner">
          <svg className="promo-icon" viewBox="0 0 24 24">
            <path d="M12 2C6.48 2 2 6.48 2 12s4.48 10 10 10 10-4.48 10-10S17.52 2 12 2zm-1 17.93c-3.95-.49-7-3.85-7-7.93 0-.62.08-1.21.21-1.79L9 15v1c0 1.1.9 2 2 2v1.93zm6.9-2.54c-.26-.81-1-1.39-1.9-1.39h-1v-3c0-.55-.45-1-1-1H8v-2h2c.55 0 1-.45 1-1V7h2c1.1 0 2-.9 2-2v-.41c2.93 1.19 5 4.06 5 7.41 0 2.08-.8 3.97-2.1 5.39z"/>
          </svg>
          <div className="promo-text-content">
             <p>Create & Distribute Your Music</p>
             <a href="https://soundsky.com" target="_blank" rel="noopener noreferrer">Visit SoundSky.com &rarr;</a>
          </div>
        </div>
      </header>

      <main className="main-content">
        <section className="controls">
          <h2>Configuration</h2>
          <div className="form-group">
            <label>Song Title</label>
            <input type="text" value={songTitle} onChange={(e) => setSongTitle(e.target.value)} placeholder="e.g. Dawai Asmara" />
          </div>
          <div className="form-group">
            <label>Artist Reference / Style</label>
            <input type="text" value={artistRef} onChange={(e) => setArtistRef(e.target.value)} placeholder="e.g. Rhoma Irama" />
          </div>
          <button className="btn btn-secondary btn-full-width" onClick={handleAssistantClick} disabled={assistantLoading} style={{ marginBottom: '1.5rem' }}>
            {assistantLoading ? <div className="spinner small"></div> : "Suggest with AI"}
          </button>
          <div className="form-group">
            <label>Genre</label>
            <select value={genre} onChange={(e) => setGenre(e.target.value)}>
              {genreOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Subgenre</label>
            <select value={subgenre} onChange={(e) => setSubgenre(e.target.value)}>
              {subgenreOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>World Music Influence</label>
             <select value={worldMusic} onChange={(e) => setWorldMusic(e.target.value)}>
               <option value="None">None</option>
              {worldMusicOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Mood</label>
            <select value={mood} onChange={(e) => setMood(e.target.value)}>
              {moodOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Theme</label>
            <select value={theme} onChange={(e) => setTheme(e.target.value)}>
               {themeOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)} 
            </select>
          </div>
          <div className="form-group">
            <label>Tempo (BPM): {tempo}</label>
            <input type="range" min="40" max="220" value={tempo} onChange={(e) => setTempo(parseInt(e.target.value))} />
          </div>
          <div className="form-group">
            <label>Key</label>
            <select value={key} onChange={(e) => setKey(e.target.value)}>
              {KEY_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Lyric Language</label>
            <select value={lyricLanguage} onChange={(e) => setLyricLanguage(e.target.value)}>
              {LYRIC_LANGUAGE_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Duration</label>
            <div className="radio-group">
                <label><input type="radio" value="4" checked={duration === "4"} onChange={(e) => setDuration(e.target.value)} /> ~4 min</label>
                <label><input type="radio" value="8" checked={duration === "8"} onChange={(e) => setDuration(e.target.value)} /> ~8 min</label>
            </div>
          </div>
          <button className="btn btn-primary btn-full-width" onClick={handleGenerate} disabled={loading}>
            {loading ? <div className="spinner small"></div> : "Generate Template"}
          </button>
        </section>

        <section className="output">
          {error && <div className="error-message">{error}</div>}
          {loading && <div className="spinner-wrapper"><div className="spinner"></div><p>Composing full lyrics and structure...</p></div>}
          {!loading && outputBlocks.length === 0 && <div className="placeholder"><p>Configure and generate to see results.</p></div>}
          {!loading && outputBlocks.length > 0 && (
            <div className="output-blocks-wrapper">
                <div className="output-block">
                    <h3>Visualizer</h3>
                    <div className="visualizer-container">
                         <MusicVisualizer tempo={tempo} mood={mood} songTitle={songTitle} artistRef={artistRef} />
                    </div>
                    <div className="form-group">
                         <input type="file" accept="audio/*" onChange={(e) => {
                                const file = e.target.files[0];
                                if(file) {
                                    setBackgroundTrack(file);
                                    if(backgroundTrackUrlRef.current) URL.revokeObjectURL(backgroundTrackUrlRef.current);
                                    setBackgroundTrackUrl(URL.createObjectURL(file));
                                }
                            }} />
                    </div>
                    {backgroundTrackUrl && <audio controls className="audio-player" src={backgroundTrackUrl} />}
                </div>
                {outputBlocks.map((block, index) => (
                    <div key={index} className="output-block">
                        <h3>{block.title}</h3>
                        <button className="btn-copy" onClick={() => navigator.clipboard.writeText(block.content)}>Copy</button>
                        <pre>{block.content}</pre>
                        {block.title === "Generated Music Template" && sources.length > 0 && (
                             <div className="info-text" style={{textAlign: 'left', marginTop: '1rem', borderTop: '1px solid #333', paddingTop: '0.5rem'}}>
                                 <strong>Sources:</strong>
                                 <ul style={{paddingLeft: '1.5rem', marginTop: '0.5rem'}}>
                                     {sources.map((s, i) => (<li key={i}><a href={s} target="_blank" rel="noopener noreferrer" style={{color: '#03dac6'}}>{s}</a></li>))}
                                 </ul>
                             </div>
                        )}
                    </div>
                ))}
                <div className="output-block image-gallery-block">
                    <h3>Band Imagery</h3>
                    <button className="btn btn-secondary btn-full-width" onClick={handleGenerateImages} disabled={imageLoading}>
                         {imageLoading ? <div className="spinner small"></div> : "Generate Images"}
                    </button>
                    {imageError && <div className="error-message">{imageError}</div>}
                    <div className="image-gallery-grid" style={{marginTop: '1.5rem'}}>
                        {generatedImages.map((src, index) => (
                            <div key={index} className="generated-image-container"><img src={src} className="generated-image" /></div>
                        ))}
                    </div>
                 </div>
            </div>
          )}
        </section>
      </main>
    </div>
  );
};

