    Target Request: "${songTitle}" in the style of "${artistRef}".

    ### CRITICAL MANDATE FOR LYRICS ###
    1. If "${songTitle}" is an existing song (by anyone), you MUST use Google Search to find the **100% ORIGINAL VERBATIM LYRICS**.
    2. DO NOT change a single word of the lyrics.
    3. DO NOT summarize. DO NOT use placeholders like "(Chorus Repeat)".
    4. You MUST transcribe the entire song: Verse 1, Chorus, Verse 2, Chorus, Bridge, Final Chorus, Outro. Every word.
    5. If there are multiple versions, use the most popular/original one.

    ### PRODUCTION MANDATE ###
    1. Rearrange the instrumentation and technical notes to fit the requested style:
       Genre: ${genre}, Subgenre: ${subgenre}, World Music: ${worldMusic}, Mood: ${mood}.
    2. All chords should be in [Square Brackets] directly above the lyrics.
    3. Include a detailed [Song Composition] section.
    4. Include a [STYLE_DESCRIPTION_SECTION] at the very end.

    TEMPLATE:
    [title: ${songTitle}]
    [artist: ${artistRef}]
    [genre: ${genre}]
    [subgenre: ${subgenre}]
    [tempo: ${tempo} BPM]
    [key: ${key}]
    [lyrics: ...]

    [STYLE_DESCRIPTION_SECTION]
    (Sonic description here)`;

    try {
      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{googleSearch: {}}],
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192,
        },
      }));

      const responseText = response.text.trim();

      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
          const chunks = response.candidates[0].groundingMetadata.groundingChunks;
          const uniqueSources = Array.from(new Set(chunks.map((chunk: any) => chunk.web?.uri).filter(u => u))) as string[];
          setSources(uniqueSources);
      }

      const summaryMarker = '[STYLE_DESCRIPTION_SECTION]';
      const summaryIndex = responseText.lastIndexOf(summaryMarker);

      if (summaryIndex !== -1) {
        setOutputBlocks([
          { title: "Generated Music Template", content: responseText.substring(0, summaryIndex).trim() },
          { title: "Style Description", content: responseText.substring(summaryIndex + summaryMarker.length).trim() },
        ]);
      } else {
        // Fallback if marker is missing: still display the text.
        setOutputBlocks([{ title: "Generated Music Template", content: responseText }]);
      }
    } catch (e) {
      setError("Failed to generate template. Quota reached or API error.");
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateImages = async () => {
    setImageLoading(true);
    setImageError(null);
    try {
      const prompt = `Cinematic photo of a music group performing "${songTitle}" in the style of "${artistRef}". High resolution, moody lighting, genre: ${genre}.`;
      const response = await callWithRetry(() => ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: prompt,
        config: { numberOfImages: 4, aspectRatio: '16:9' },
      }));
      setGeneratedImages(response.generatedImages.map(img => `data:image/jpeg;base64,${img.image.imageBytes}`));
    } catch (e) {
      setImageError("Image generation failed.");
    } finally {
      setImageLoading(false);
    }
  };

  return (
    <div className="container">
      <header>
        <h1>Warga Digital Studio</h1>
        <div className="promo-banner">
          <p>Create & Distribute Your Music</p>
        </div>
      </header>

      <main className="main-content">
        <section className="controls">
          <h2>Configuration</h2>
          <div className="form-group">
            <label>Song Title</label>
            <input type="text" value={songTitle} onChange={(e) => setSongTitle(e.target.value)} placeholder="e.g. Dawai Asmara" />
          </div>
          <div className="form-group">
            <label>Artist Style</label>
            <input type="text" value={artistRef} onChange={(e) => setArtistRef(e.target.value)} placeholder="e.g. Waldjinah" />
          </div>
          <button className="btn btn-secondary btn-full-width" onClick={handleAssistantClick} disabled={assistantLoading}>
            {assistantLoading ? <div className="spinner small"></div> : "Auto-Fill Suggestions"}
          </button>

          <div className="form-group" style={{marginTop: '1.5rem'}}>
            <label>Genre</label>
            <select value={genre} onChange={(e) => setGenre(e.target.value)}>
              {genreOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Subgenre</label>
            <select value={subgenre} onChange={(e) => setSubgenre(e.target.value)}>
              {subgenreOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Mood</label>
            <select value={mood} onChange={(e) => setMood(e.target.value)}>
              {moodOptions.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Tempo (BPM): {tempo}</label>
            <input type="range" min="40" max="220" value={tempo} onChange={(e) => setTempo(parseInt(e.target.value))} />
          </div>

          <button className="btn btn-primary btn-full-width" onClick={handleGenerate} disabled={loading}>
            {loading ? <div className="spinner small"></div> : "Generate Full Lyrics & Structure"}
          </button>
        </section>

        <section className="output">
          {error && <div className="error-message">{error}</div>}
          {loading && <div className="spinner-wrapper"><div className="spinner"></div><p>Searching for official lyrics and composing arrangement...</p></div>}

          {outputBlocks.length > 0 && (
            <div className="output-blocks-wrapper">
                <div className="output-block">
                    <h3>Real-time Visualizer</h3>
                    <MusicVisualizer tempo={tempo} mood={mood} songTitle={songTitle} artistRef={artistRef} />
                    <div className="form-group" style={{marginTop: '1rem'}}>
                         <input type="file" accept="audio/*" onChange={(e) => {
                                const file = e.target.files?.[0];
                                if(file) setBackgroundTrackUrl(URL.createObjectURL(file));
                            }} />
                    </div>
                    {backgroundTrackUrl && <audio controls className="audio-player" src={backgroundTrackUrl} />}
                </div>

                {outputBlocks.map((block, i) => (
                    <div key={i} className="output-block">
                        <h3>{block.title}</h3>
                        <button className="btn-copy" onClick={() => navigator.clipboard.writeText(block.content)}>Copy</button>
                        <pre>{block.content}</pre>
                        {i === 0 && sources.length > 0 && (
                          <div className="info-text" style={{textAlign: 'left', borderTop: '1px solid #333', marginTop: '1rem', paddingTop: '1rem'}}>
                            <strong>Lyric Sources Used:</strong>
                            <ul>{sources.map((s, j) => <li key={j}><a href={s} target="_blank" rel="noopener noreferrer">{s}</a></li>)}</ul>
                          </div>
                        )}
                    </div>
                ))}

                <div className="output-block">
                    <h3>AI Band Imagery</h3>
                    <button className="btn btn-secondary btn-full-width" onClick={handleGenerateImages} disabled={imageLoading}>
                         {imageLoading ? <div className="spinner small"></div> : "Generate Visuals"}
                    </button>
                    <div className="image-gallery-grid" style={{marginTop: '1.5rem'}}>
                        {generatedImages.map((src, idx) => <img key={idx} src={src} className="generated-image" />)}
                    </div>
                </div>
            </div>
          )}
        </section>
      </main>
    </div>
  );
};

