// --- MultiSelect Component ---
const MultiSelect = ({ label, options, selected, onChange, max = 5 }: { label: string, options: string[], selected: string[], onChange: (val: string[]) => void, max?: number }) => {
  const toggle = (opt: string) => {
    if (selected.includes(opt)) {
      onChange(selected.filter(s => s !== opt));
    } else {
      if (selected.length < max) {
        onChange([...selected, opt]);
      }
    }
  };

  return (
    <div className="form-group">
      <div className="label-row">
        <label>{label}</label>
        <span className="count-badge">{selected.length}/{max}</span>
      </div>
      <div className="chip-grid">
        {options.map(opt => (
          <button
            key={opt}
            className={`chip ${selected.includes(opt) ? 'selected' : ''}`}
            onClick={() => toggle(opt)}
          >
            {opt}
          </button>
        ))}
      </div>
    </div>
  );
};

const MusicVisualizer = ({ tempo, moods, songTitle, artistRef }: { tempo: number, moods: string[], songTitle: string, artistRef: string }) => {
  const sketchRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const sketch = (p) => {
      let particles: any[] = [];
      // Use the first selected mood to determine color palette, or default
      const primaryMood = moods.length > 0 ? moods[0] : 'Default';
      const colors = MOOD_COLORS[primaryMood as keyof typeof MOOD_COLORS] || MOOD_COLORS.Default;

      const beatTime = (60 / tempo) * 1000;
      let lastBeat = 0;
      let beatSize = 1;

      class Particle {
        pos: any; vel: any; acc: any; maxSpeed: number; color: any;
        constructor() {
          this.pos = p.createVector(p.random(p.width), p.random(p.height));
          this.vel = p.createVector(p.random(-1, 1), p.random(-1, 1));
          this.acc = p.createVector(0, 0);
          this.maxSpeed = 2;
          this.color = p.color(p.random(colors));
        }
        update() {
          this.vel.add(this.acc);
          this.vel.limit(this.maxSpeed);
          this.pos.add(this.vel);
          this.acc.mult(0);
        }
        edges() {
          if (this.pos.x > p.width) this.pos.x = 0;
          if (this.pos.x < 0) this.pos.x = p.width;
          if (this.pos.y > p.height) this.pos.y = 0;
          if (this.pos.y < 0) this.pos.y = p.height;
        }
        display() {
          p.noStroke();
          p.fill(this.color);
          p.ellipse(this.pos.x, this.pos.y, 4, 4);
        }
      }

      p.setup = () => {
        const container = sketchRef.current;
        if (container) {
          p.createCanvas(container.offsetWidth, 400).parent(sketchRef.current);
          for (let i = 0; i < 100; i++) particles.push(new Particle());
        }
      };

      p.draw = () => {
        p.background(18, 18, 18, 50);
        p.textAlign(p.CENTER, p.CENTER);
        p.fill(255, 255, 255, 100); 
        p.textSize(28);
        p.text(songTitle || 'Untitled Song', p.width / 2, p.height / 2 - 20);
        p.textSize(18);
        p.fill(255, 255, 255, 80);
        p.text(artistRef || 'Independent Artist', p.width / 2, p.height / 2 + 20);
        const currentTime = p.millis();
        if (currentTime - lastBeat > beatTime) {
            lastBeat = currentTime;
            beatSize = 1.5;
        }
        beatSize = p.lerp(beatSize, 1, 0.1); 
        const orbSize = p.width / 4 * beatSize;
        const mainColor = p.color(colors[0]);
        mainColor.setAlpha(150);
        p.fill(mainColor);
        p.noStroke();
        p.ellipse(p.width / 2, p.height / 2, orbSize, orbSize);
        for (let particle of particles) {
          particle.update();
          particle.edges();
          particle.display();
        }
      };
      p.windowResized = () => {
          const container = sketchRef.current;
          if(container) p.resizeCanvas(container.offsetWidth, 400);
      };
    };
    let p5Instance = new p5(sketch, sketchRef.current);
    return () => p5Instance.remove();
  }, [tempo, moods, songTitle, artistRef]);

  return <div ref={sketchRef} className="visualizer-canvas"></div>;
};

const App = () => {
  const [genreOptions, setGenreOptions] = useState(INITIAL_GENRE_OPTIONS);
  const [subgenreOptions, setSubgenreOptions] = useState(INITIAL_SUBGENRE_OPTIONS);

  // These are now purely for the MultiSelect options list
  const [worldMusicOptions, setWorldMusicOptions] = useState(INITIAL_WORLD_MUSIC_OPTIONS);
  const [moodOptions, setMoodOptions] = useState(MOOD_OPTIONS);
  const [themeOptions, setThemeOptions] = useState(THEME_OPTIONS);

  // Genre and Subgenre now support multiple selections (arrays)
  const [genres, setGenres] = useState<string[]>([]);
  const [subgenres, setSubgenres] = useState<string[]>([]);

  const [worldMusicInfluences, setWorldMusicInfluences] = useState<string[]>([]);
  const [moods, setMoods] = useState<string[]>([]);
  const [themes, setThemes] = useState<string[]>([]);

  const [lyricLanguage, setLyricLanguage] = useState(LYRIC_LANGUAGE_OPTIONS[0]);
  const [duration, setDuration] = useState("4");
  const [songTitle, setSongTitle] = useState("");
  const [artistRef, setArtistRef] = useState("");
  const [tempo, setTempo] = useState(120);
  const [key, setKey] = useState(KEY_OPTIONS[0]);
  const [timeSignature, setTimeSignature] = useState(TIME_SIGNATURE_OPTIONS[0]);
  const [backgroundTrackUrl, setBackgroundTrackUrl] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [assistantLoading, setAssistantLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [outputBlocks, setOutputBlocks] = useState<any[]>([]);
  const [sources, setSources] = useState<string[]>([]); 
  const [imageLoading, setImageLoading] = useState(false);
  const [generatedImages, setGeneratedImages] = useState<string[]>([]);
  const [imageError, setImageError] = useState<string | null>(null);

  const backgroundTrackUrlRef = useRef(backgroundTrackUrl);
  backgroundTrackUrlRef.current = backgroundTrackUrl;

  useEffect(() => {
    return () => {
      if (backgroundTrackUrlRef.current) URL.revokeObjectURL(backgroundTrackUrlRef.current);
    };
  }, []);

  const handleAssistantClick = async () => {
    setAssistantLoading(true);
    setError(null);
    try {
      const isSpecificSong = songTitle.trim().length > 0;
      let prompt = `Act as a Music Intelligence Agent. User requested: "${songTitle}" in the style of "${artistRef}".
      Determine if this is an existing song. Find its ORIGINAL genre, BPM, and Key.
      If it's a new idea, suggest the best parameters.

      For "genre", "subgenre", "moods", "worldMusic", and "themes", provide an ARRAY of strings (up to 3 for genre/subgenre, 5 for others).

      Return ONLY valid JSON:
      {
        "genre": ["MainGenre", "SecondaryGenre"], 
        "subgenre": ["Sub1", "Sub2"], 
        "worldMusic": ["Tag1", "Tag2"], 
        "moods": ["Tag1", "Tag2"], 
        "themes": ["Tag1", "Tag2"], 
        "tempo": Number, "key": "...", "timeSignature": "...", "lyricLanguage": "...", "durationMinutes": Number
      }`;

      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
            tools: isSpecificSong ? [{ googleSearch: {} }] : [],
            responseMimeType: isSpecificSong ? undefined : "application/json"
        },
      }));

      let text = response.text || "";
      let suggestions;
      try {
          text = text.replace(/```json/g, "").replace(/```/g, "").trim();
          const start = text.indexOf('{');
          const end = text.lastIndexOf('}');
          suggestions = JSON.parse(text.substring(start, end + 1));
      } catch (e) {
          throw new Error("Failed to parse AI suggestions.");
      }

      if (suggestions.genre) {
          const arr = Array.isArray(suggestions.genre) ? suggestions.genre : [suggestions.genre];
          setGenreOptions(prev => Array.from(new Set([...arr, ...prev])));
          setGenres(arr.slice(0, 3));
      }
      if (suggestions.subgenre) {
          const arr = Array.isArray(suggestions.subgenre) ? suggestions.subgenre : [suggestions.subgenre];
          setSubgenreOptions(prev => Array.from(new Set([...arr, ...prev])));
          setSubgenres(arr.slice(0, 3));
      }

      if (suggestions.worldMusic) {
          const arr = Array.isArray(suggestions.worldMusic) ? suggestions.worldMusic : [suggestions.worldMusic];
          setWorldMusicOptions(prev => Array.from(new Set([...arr, ...prev])));
          setWorldMusicInfluences(arr.slice(0, 5));
      }
      if (suggestions.moods) {
          const arr = Array.isArray(suggestions.moods) ? suggestions.moods : [suggestions.moods];
          setMoodOptions(prev => Array.from(new Set([...arr, ...prev])));
          setMoods(arr.slice(0, 5));
      }
      if (suggestions.themes) {
          const arr = Array.isArray(suggestions.themes) ? suggestions.themes : [suggestions.themes];
          setThemeOptions(prev => Array.from(new Set([...arr, ...prev])));
          setThemes(arr.slice(0, 5));
      }

      if (suggestions.tempo) setTempo(Math.round(Math.max(40, Math.min(220, suggestions.tempo))));
      if (suggestions.key) setKey(KEY_OPTIONS.find(k => suggestions.key.includes(k)) || KEY_OPTIONS[0]);
      if (suggestions.timeSignature && TIME_SIGNATURE_OPTIONS.includes(suggestions.timeSignature)) setTimeSignature(suggestions.timeSignature);
      if (suggestions.lyricLanguage) {
          const matchedLang = LYRIC_LANGUAGE_OPTIONS.find(l => suggestions.lyricLanguage.toLowerCase().includes(l.toLowerCase()));
          if (matchedLang) setLyricLanguage(matchedLang);
      }
      if (suggestions.durationMinutes) setDuration(suggestions.durationMinutes >= 6 ? "8" : "4");

    } catch (e) {
      setError("AI assistant failed. Please try again.");
    } finally {
      setAssistantLoading(false);
    }
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setOutputBlocks([]);
    setGeneratedImages([]);
    setSources([]);

    const isSpecificSong = songTitle.trim().length > 0;

    // Convert arrays to comma-separated strings for the prompt
    const genreStr = genres.join(", ") || "General";
    const subgenreStr = subgenres.join(", ") || "General";
    const moodStr = moods.join(", ") || "Varied";
    const themeStr = themes.join(", ") || "General";
    const worldStr = worldMusicInfluences.join(", ") || "None";

    const prompt = `TARGET: "${songTitle}" by/style of "${artistRef}".

    PARAMS:
    - Genre: ${genreStr}
    - Subgenre: ${subgenreStr}
    - Moods: ${moodStr}
    - Themes: ${themeStr}
    - World: ${worldStr}
    - Tech: ${tempo} BPM, ${key}, ${timeSignature}, ${duration} min, ${lyricLanguage}.

    INSTRUCTIONS:
    1. If existing song: Transcribe official lyrics/chords exactly.
    2. If new song: Compose original lyrics/chords matching params.
    3. FILL THE TEMPLATE BELOW EXACTLY. DO NOT DEVIATE.

    TEMPLATE:
    [Title: ${songTitle}]
    [Artist: ${artistRef}]
    [Genre: ${genreStr}]
    [Subgenre: ${subgenreStr}]
    [World Music: ${worldStr}]
    [Moods: ${moodStr}]
    [Themes: ${themeStr}]
    [Tempo: ${tempo} BPM]
    [Key: ${key}]
    [Time Signature: ${timeSignature}]
    [Duration: ${duration === "4" ? "~4 min" : "~8 min"}]
    [Language: ${lyricLanguage}]

    [Structure Tag]
    [Chord] [Chord]
    Lyrics line...

    [STYLE_DESCRIPTION_SECTION]
    (Description)`;

    const systemInstruction = `You are a strict Music Engine. 
    1. FORMATTING RULES:
       - USE ONLY SQUARE BRACKETS [] for metadata keys and structure sections. 
       - NO MARKDOWN (no **, no ##). 
       - NO PARENTHESES ().
    2. CONTENT RULES:
       - If song exists: VERBATIM LYRICS.
       - If song is new: ORIGINAL CREATIVE LYRICS.
    3. METADATA:
       - You MUST output the Metadata Block at the very top.
    `;

    try {
      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{googleSearch: {}}],
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192,
          systemInstruction: systemInstruction,
        },
      }));

      const responseText = response.text.trim();

      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
          const chunks = response.candidates[0].groundingMetadata.groundingChunks;
          const uniqueSources = Array.from(new Set(chunks.map((chunk: any) => chunk.web?.uri).filter(u => u))) as string[];
          setSources(uniqueSources);
      }

      const summaryMarker = '[STYLE_DESCRIPTION_SECTION]';
      const summaryIndex = responseText.lastIndexOf(summaryMarker);

      if (summaryIndex !== -1) {
        setOutputBlocks([
          { title: "Generated Music Template", content: responseText.substring(0, summaryIndex).trim() },
          { title: "Style Description", content: responseText.substring(summaryIndex + summaryMarker.length).trim() },
        ]);
      } else {
        // Fallback if marker is missing: still display the text.
        setOutputBlocks([{ title: "Generated Music Template", content: responseText }]);
      }
    } catch (e) {
      setError("Failed to generate template. Quota reached or API error.");
    } finally {
      setLoading(false);
    }
  };

  const handleGenerateImages = async () => {
    setImageLoading(true);
    setImageError(null);

    const genreStr = genres.join(", ");
    const moodStr = moods.join(", ");

    try {
      const prompt = `Cinematic photo of a music group performing "${songTitle}" in the style of "${artistRef}". High resolution, moody lighting, genre: ${genreStr}, mood: ${moodStr}.`;
      const response = await callWithRetry(() => ai.models.generateImages({
        model: 'imagen-4.0-generate-001',
        prompt: prompt,
        config: { numberOfImages: 4, aspectRatio: '16:9' },
      }));
      setGeneratedImages(response.generatedImages.map(img => `data:image/jpeg;base64,${img.image.imageBytes}`));
    } catch (e) {
      setImageError("Image generation failed.");
    } finally {
      setImageLoading(false);
    }
  };

  return (
    <div className="container">
      <header>
        <h1>Warga Digital Studio</h1>
        <div className="promo-banner">
          <p>Create & Distribute Your Music</p>
        </div>
      </header>

      <main className="main-content">
        <section className="controls">
          <h2>Configuration</h2>
          <div className="form-group">
            <label>Song Title</label>
            <input type="text" value={songTitle} onChange={(e) => setSongTitle(e.target.value)} placeholder="e.g. Dawai Asmara" />
          </div>
          <div className="form-group">
            <label>Artist Style</label>
            <input type="text" value={artistRef} onChange={(e) => setArtistRef(e.target.value)} placeholder="e.g. Waldjinah" />
          </div>
          <button className="btn btn-secondary btn-full-width" onClick={handleAssistantClick} disabled={assistantLoading}>
            {assistantLoading ? <div className="spinner small"></div> : "Auto-Fill Suggestions"}
          </button>

          <MultiSelect 
            label="Genre (Select up to 3)" 
            options={genreOptions} 
            selected={genres} 
            onChange={setGenres} 
            max={3} 
          />

          <MultiSelect 
            label="Subgenre (Select up to 3)" 
            options={subgenreOptions} 
            selected={subgenres} 
            onChange={setSubgenres} 
            max={3} 
          />

          {/* Multi-Select Components */}
          <MultiSelect 
            label="Mood (Select up to 5)" 
            options={moodOptions} 
            selected={moods} 
            onChange={setMoods} 
            max={5} 
          />

          <MultiSelect 
            label="Theme (Select up to 5)" 
            options={themeOptions} 
            selected={themes} 
            onChange={setThemes} 
            max={5} 
          />

          <MultiSelect 
            label="World Music Influence (Select up to 5)" 
            options={worldMusicOptions} 
            selected={worldMusicInfluences} 
            onChange={setWorldMusicInfluences} 
            max={5} 
          />

          <div className="form-group">
            <label>Tempo (BPM): {tempo}</label>
            <input type="range" min="40" max="220" value={tempo} onChange={(e) => setTempo(parseInt(e.target.value))} />
          </div>

           <div className="form-group">
            <label>Key</label>
            <select value={key} onChange={(e) => setKey(e.target.value)}>
              {KEY_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
          <div className="form-group">
            <label>Time Signature</label>
            <select value={timeSignature} onChange={(e) => setTimeSignature(e.target.value)}>
              {TIME_SIGNATURE_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>

          <div className="form-group">
            <label>Lyric Language</label>
            <select value={lyricLanguage} onChange={(e) => setLyricLanguage(e.target.value)}>
              {LYRIC_LANGUAGE_OPTIONS.map(opt => <option key={opt} value={opt}>{opt}</option>)}
            </select>
          </div>
           <div className="form-group">
            <label>Duration</label>
            <div style={{display: 'flex', gap: '1rem', marginTop: '0.5rem'}}>
                <label style={{cursor: 'pointer', display: 'flex', alignItems: 'center'}}>
                    <input type="radio" value="4" checked={duration === "4"} onChange={(e) => setDuration(e.target.value)} style={{marginRight: '0.5rem', width: 'auto'}} /> ~4 min
                </label>
                <label style={{cursor: 'pointer', display: 'flex', alignItems: 'center'}}>
                    <input type="radio" value="8" checked={duration === "8"} onChange={(e) => setDuration(e.target.value)} style={{marginRight: '0.5rem', width: 'auto'}} /> ~8 min
                </label>
            </div>
          </div>

          <button className="btn btn-primary btn-full-width" onClick={handleGenerate} disabled={loading} style={{marginTop: '1.5rem'}}>
            {loading ? <div className="spinner small"></div> : "Generate Full Lyrics & Structure"}
          </button>
        </section>

        <section className="output">
          {error && <div className="error-message">{error}</div>}
          {loading && <div className="spinner-wrapper"><div className="spinner"></div><p>Searching for official lyrics and composing arrangement...</p></div>}

          {outputBlocks.length > 0 && (
            <div className="output-blocks-wrapper">
                <div className="output-block">
                    <h3>Real-time Visualizer</h3>
                    <MusicVisualizer tempo={tempo} moods={moods} songTitle={songTitle} artistRef={artistRef} />
                    <div className="form-group" style={{marginTop: '1rem'}}>
                         <input type="file" accept="audio/*" onChange={(e) => {
                                const file = e.target.files?.[0];
                                if(file) setBackgroundTrackUrl(URL.createObjectURL(file));
                            }} />
                    </div>
                    {backgroundTrackUrl && <audio controls className="audio-player" src={backgroundTrackUrl} />}
                </div>

                {outputBlocks.map((block, i) => (
                    <div key={i} className="output-block">
                        <h3>{block.title}</h3>
                        <button className="btn-copy" onClick={() => navigator.clipboard.writeText(block.content)}>Copy</button>
                        <pre>{block.content}</pre>
                        {i === 0 && sources.length > 0 && (
                          <div className="info-text" style={{textAlign: 'left', borderTop: '1px solid #333', marginTop: '1rem', paddingTop: '1rem'}}>
                            <strong>Lyric Sources Used:</strong>
                            <ul>{sources.map((s, j) => <li key={j}><a href={s} target="_blank" rel="noopener noreferrer">{s}</a></li>)}</ul>
                          </div>
                        )}
                    </div>
                ))}

                <div className="output-block">
                    <h3>AI Band Imagery</h3>
                    <button className="btn btn-secondary btn-full-width" onClick={handleGenerateImages} disabled={imageLoading}>
                         {imageLoading ? <div className="spinner small"></div> : "Generate Visuals"}
                    </button>
                    <div className="image-gallery-grid" style={{marginTop: '1.5rem'}}>
                        {generatedImages.map((src, idx) => <img key={idx} src={src} className="generated-image" />)}
                    </div>
                </div>
            </div>
          )}
        </section>
      </main>
    </div>
  );
};

