// --- MultiSelect Component ---
const MultiSelect = ({ label, options, selected, onChange, max = 5 }: { label: string, options: string[], selected: string[], onChange: (val: string[]) => void, max?: number }) => {
  const toggle = (opt: string) => {
    if (selected.includes(opt)) {
      onChange(selected.filter(s => s !== opt));
    } else {
      if (selected.length < max) {
        onChange([...selected, opt]);
      }
    }
  };

  return (
    <div className="form-group">
      <div className="label-row">
        <label>{label}</label>
        <span className="count-badge">{selected.length}/{max}</span>
      </div>
      <div className="chip-grid">
        {options.map(opt => (
          <button
            key={opt}
            className={`chip ${selected.includes(opt) ? 'selected' : ''}`}
            onClick={() => toggle(opt)}
          >
            {opt}
          </button>
        ))}
      </div>
    </div>
  );
};

const MusicVisualizer = ({ tempo, moods, songTitle, artistRef }: { tempo: number, moods: string[], songTitle: string, artistRef: string }) => {
  const sketchRef = useRef<HTMLDivElement>(null);

  useEffect(() => {
    const sketch = (p) => {
      let particles: any[] = [];
      // Use the first selected mood to determine color palette, or default
      const primaryMood = moods.length > 0 ? moods[0] : 'Default';
      const colors = MOOD_COLORS[primaryMood as keyof typeof MOOD_COLORS] || MOOD_COLORS.Default;

      const beatTime = (60 / tempo) * 1000;
      let lastBeat = 0;
      let beatSize = 1;

      class Particle {
        pos: any; vel: any; acc: any; maxSpeed: number; color: any;
        constructor() {
          this.pos = p.createVector(p.random(p.width), p.random(p.height));
          this.vel = p.createVector(p.random(-1, 1), p.random(-1, 1));
          this.acc = p.createVector(0, 0);
          this.maxSpeed = 2;
          this.color = p.color(p.random(colors));
        }
        update() {
          this.vel.add(this.acc);
          this.vel.limit(this.maxSpeed);
          this.pos.add(this.vel);
          this.acc.mult(0);
        }
        edges() {
          if (this.pos.x > p.width) this.pos.x = 0;
          if (this.pos.x < 0) this.pos.x = p.width;
          if (this.pos.y > p.height) this.pos.y = 0;
          if (this.pos.y < 0) this.pos.y = p.height;
        }
        display() {
          p.noStroke();
          p.fill(this.color);
          p.ellipse(this.pos.x, this.pos.y, 4, 4);
        }
      }

      p.setup = () => {
        const container = sketchRef.current;
        if (container) {
          p.createCanvas(container.offsetWidth, 400).parent(sketchRef.current);
          for (let i = 0; i < 100; i++) particles.push(new Particle());
        }
      };

      p.draw = () => {
        p.background(18, 18, 18, 50);
        p.textAlign(p.CENTER, p.CENTER);
        p.fill(255, 255, 255, 100); 
        p.textSize(28);
        p.text(songTitle || 'Untitled Song', p.width / 2, p.height / 2 - 20);
        p.textSize(18);
        p.fill(255, 255, 255, 80);
        p.text(artistRef || 'Independent Artist', p.width / 2, p.height / 2 + 20);
        const currentTime = p.millis();
        if (currentTime - lastBeat > beatTime) {
            lastBeat = currentTime;
            beatSize = 1.5;
        }
        beatSize = p.lerp(beatSize, 1, 0.1); 
        const orbSize = p.width / 4 * beatSize;
        const mainColor = p.color(colors[0]);
        mainColor.setAlpha(150);
        p.fill(mainColor);
        p.noStroke();
        p.ellipse(p.width / 2, p.height / 2, orbSize, orbSize);
        for (let particle of particles) {
          particle.update();
          particle.edges();
          particle.display();
        }
      };
      p.windowResized = () => {
          const container = sketchRef.current;
          if(container) p.resizeCanvas(container.offsetWidth, 400);
      };
    };
    let p5Instance = new p5(sketch, sketchRef.current);
    return () => p5Instance.remove();
  }, [tempo, moods, songTitle, artistRef]);

  return <div ref={sketchRef} className="visualizer-canvas"></div>;
};

