  const [worldMusicInfluences, setWorldMusicInfluences] = useState<string[]>([]);
  const [moods, setMoods] = useState<string[]>([]);
  const [themes, setThemes] = useState<string[]>([]);

  const [lyricLanguage, setLyricLanguage] = useState(LYRIC_LANGUAGE_OPTIONS[0]);
  const [duration, setDuration] = useState("4");
  const [songTitle, setSongTitle] = useState("");
  const [artistRef, setArtistRef] = useState("");
  const [tempo, setTempo] = useState(120);
  const [key, setKey] = useState(KEY_OPTIONS[0]);
  const [timeSignature, setTimeSignature] = useState(TIME_SIGNATURE_OPTIONS[0]);
  const [backgroundTrackUrl, setBackgroundTrackUrl] = useState<string | null>(null);

  const [loading, setLoading] = useState(false);
  const [assistantLoading, setAssistantLoading] = useState(false);
  const [error, setError] = useState<string | null>(null);
  const [outputBlocks, setOutputBlocks] = useState<any[]>([]);
  const [sources, setSources] = useState<string[]>([]); 
  const [imageLoading, setImageLoading] = useState(false);
  const [generatedImages, setGeneratedImages] = useState<string[]>([]);
  const [imageError, setImageError] = useState<string | null>(null);

  const backgroundTrackUrlRef = useRef(backgroundTrackUrl);
  backgroundTrackUrlRef.current = backgroundTrackUrl;

  useEffect(() => {
    return () => {
      if (backgroundTrackUrlRef.current) URL.revokeObjectURL(backgroundTrackUrlRef.current);
    };
  }, []);

  const handleAssistantClick = async () => {
    setAssistantLoading(true);
    setError(null);
    try {
      const isSpecificSong = songTitle.trim().length > 0;
      let prompt = `Act as a Music Intelligence Agent. User requested: "${songTitle}" in the style of "${artistRef}".
      Determine if this is an existing song. 
      Use Google Search to find its EXACT ORIGINAL BPM, Key, and Genres.
      If it's a new idea, suggest the best parameters.

      For "genre", "subgenre", "moods", "worldMusic", and "themes", provide an ARRAY of strings (up to 3 for genre/subgenre, 5 for others).

      Return ONLY valid JSON:
      {
        "genre": ["MainGenre", "SecondaryGenre"], 
        "subgenre": ["Sub1", "Sub2"], 
        "worldMusic": ["Tag1", "Tag2"], 
        "moods": ["Tag1", "Tag2"], 
        "themes": ["Tag1", "Tag2"], 
        "tempo": Number, "key": "...", "timeSignature": "...", "lyricLanguage": "...", "durationMinutes": Number
      }`;

      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-flash-preview',
        contents: prompt,
        config: { 
            tools: isSpecificSong ? [{ googleSearch: {} }] : [],
            responseMimeType: isSpecificSong ? undefined : "application/json"
        },
      }));

      let text = response.text || "";
      let suggestions;
      try {
          text = text.replace(/```json/g, "").replace(/```/g, "").trim();
          const start = text.indexOf('{');
          const end = text.lastIndexOf('}');
          suggestions = JSON.parse(text.substring(start, end + 1));
      } catch (e) {
          throw new Error("Failed to parse AI suggestions.");
      }

      if (suggestions.genre) {
          const arr = Array.isArray(suggestions.genre) ? suggestions.genre : [suggestions.genre];
          setGenreOptions(prev => Array.from(new Set([...arr, ...prev])));
          setGenres(arr.slice(0, 3));
      }
      if (suggestions.subgenre) {
          const arr = Array.isArray(suggestions.subgenre) ? suggestions.subgenre : [suggestions.subgenre];
          setSubgenreOptions(prev => Array.from(new Set([...arr, ...prev])));
          setSubgenres(arr.slice(0, 3));
      }

      if (suggestions.worldMusic) {
          const arr = Array.isArray(suggestions.worldMusic) ? suggestions.worldMusic : [suggestions.worldMusic];
          setWorldMusicOptions(prev => Array.from(new Set([...arr, ...prev])));
          setWorldMusicInfluences(arr.slice(0, 5));
      }
      if (suggestions.moods) {
          const arr = Array.isArray(suggestions.moods) ? suggestions.moods : [suggestions.moods];
          setMoodOptions(prev => Array.from(new Set([...arr, ...prev])));
          setMoods(arr.slice(0, 5));
      }
      if (suggestions.themes) {
          const arr = Array.isArray(suggestions.themes) ? suggestions.themes : [suggestions.themes];
          setThemeOptions(prev => Array.from(new Set([...arr, ...prev])));
          setThemes(arr.slice(0, 5));
      }

      // Sync menu state with AI suggestions
      if (suggestions.tempo) setTempo(Math.round(Math.max(40, Math.min(220, suggestions.tempo))));
      if (suggestions.key) setKey(KEY_OPTIONS.find(k => suggestions.key.includes(k)) || KEY_OPTIONS[0]);
      if (suggestions.timeSignature && TIME_SIGNATURE_OPTIONS.includes(suggestions.timeSignature)) setTimeSignature(suggestions.timeSignature);
      if (suggestions.lyricLanguage) {
          const matchedLang = LYRIC_LANGUAGE_OPTIONS.find(l => suggestions.lyricLanguage.toLowerCase().includes(l.toLowerCase()));
          if (matchedLang) setLyricLanguage(matchedLang);
      }
      if (suggestions.durationMinutes) setDuration(suggestions.durationMinutes >= 6 ? "8" : "4");

    } catch (e) {
      setError("AI assistant failed. Please try again.");
    } finally {
      setAssistantLoading(false);
    }
  };

  const handleGenerate = async () => {
    setLoading(true);
    setError(null);
    setOutputBlocks([]);
    setGeneratedImages([]);
    setSources([]);

    const isSpecificSong = songTitle.trim().length > 0;

    // Convert arrays to comma-separated strings for the prompt
    const genreStr = genres.join(", ") || "General";
    const subgenreStr = subgenres.join(", ") || "General";
    const moodStr = moods.join(", ") || "Varied";
    const themeStr = themes.join(", ") || "General";
    const worldStr = worldMusicInfluences.join(", ") || "None";

    const prompt = `ACT AS A WORLD-CLASS MUSIC PRODUCER.
    Target: "${songTitle}" (Style: "${artistRef}")
    User Input Context: Genre [${genreStr}], Moods [${moodStr}], User Input Tempo: [${tempo} BPM].

    MANDATE:
    1. SYNCHRONIZATION & ACCURACY:
       - Use Google Search to find if "${songTitle}" exists.
       - **IF EXISTING SONG**: You MUST use the **REAL STUDIO BPM** and **KEY** found via search. **OVERRIDE** the user's manual input (e.g., if user says 120 but song is 74, USE 74).
       - **IF NEW SONG**: Use the user's input parameters strictly.
    2. PRODUCTION SHEET:
       - Generate a "Full Studio Production Sheet".
       - FOR EVERY SECTION, you MUST include:
         [Instrumentation: ...]
         [Vocals: ...]
         [SFX: ...] (Sound Effects, ambience, textures - MUST BE BELOW VOCALS)
    3. LYRICS:
       - If existing: REAL lyrics.
       - If new: Creative original lyrics.

    STRICT FORMAT TEMPLATE (Follow this Pattern):
    [Title: ${songTitle}]
    [Artist: ${artistRef}]
    [Genre: ${genreStr}]
    [Subgenre: ${subgenreStr}]
    [World Music: ${worldStr}]
    [Moods: ${moodStr}]
    [Themes: ${themeStr}]
    [Tempo: (INSERT ACTUAL DETECTED BPM HERE) BPM]
    [Key: ${key}]
    [Time Signature: ${timeSignature}]
    [Duration: ${duration === "4" ? "~4 min" : "~8 min"}]
    [Language: ${lyricLanguage}]

    [Verse 1]
    [Instrumentation: Lo-fi piano loops, dusty vinyl crackle, deep sub bass]
    [Vocals: Whisper-rap, intimate, close-mic]
    [SFX: Distant sirens, rain texture]
    [Am]            [Em]
    Lyrics text here...

    [Chorus]
    [Instrumentation: Wall of sound guitars, crashing cymbals, synth lead]
    [Vocals: Layered harmonies, anthemic shouting]
    [SFX: White noise risers, explosion impact]
    [C]             [G]
    Lyrics text here...

    [Bridge]
    [Solo: Electric Guitar, sweeping arpeggios, high gain, layered delay]
    [Vocals: Guttural growls, rhythmic chanting]
    [SFX: Reverse cymbals, glitch stutter]
    [Dm]            [Am]
    Lyrics text here...

    [STYLE_DESCRIPTION_SECTION]
    (Description)`;

    const systemInstruction = `You are an expert Music Arranger.
    RULES:
    1. **MAX LENGTH**: Keep output under 5000 characters. Be concise with descriptions but detailed with musical tags.
    2. **FORMATTING**: 
       - KEY metadata and Structure Sections in [Square Brackets].
       - NO Markdown (**bold**). NO Parentheses ().
       - SFX tag MUST appear below Vocal tag.
    3. **PRIORITY**: If the song is a known hit, ACCURACY to the original recording (Tempo, Key, Style) supercedes user menu inputs.
    4. **CONTENT**: Output must look like a professional studio chord chart.`;

    try {
      const response = await callWithRetry(() => ai.models.generateContent({
        model: 'gemini-3-pro-preview',
        contents: prompt,
        config: {
          tools: [{googleSearch: {}}],
          thinkingConfig: { thinkingBudget: 2048 },
          maxOutputTokens: 8192,
          systemInstruction: systemInstruction,
        },
      }));

      const responseText = response.text.trim();

      // --- SYNC UI STATE WITH RESULT (Menu Synchronization) ---
      // Try to extract the *real* tempo and key decided by AI/Search and update the slider/dropdown
      try {
        const tempoMatch = responseText.match(/\[Tempo:\s*(\d+)\s*BPM\]/i);
        if (tempoMatch && tempoMatch[1]) {
           const parsedTempo = parseInt(tempoMatch[1]);
           if (!isNaN(parsedTempo) && parsedTempo >= 40 && parsedTempo <= 220) {
               setTempo(parsedTempo); // This syncs the slider
           }
        }

        const keyMatch = responseText.match(/\[Key:\s*([^\]]+)\]/i);
        if (keyMatch && keyMatch[1]) {
           const parsedKey = keyMatch[1].trim();
           // Find the closest matching option in KEY_OPTIONS (case-insensitive)
           const validKey = KEY_OPTIONS.find(k => k.toLowerCase() === parsedKey.toLowerCase());
           if (validKey) setKey(validKey); // This syncs the dropdown
        }
      } catch (syncError) {
        console.warn("Failed to sync menu with result:", syncError);
      }
      // -----------------------------------------------------

      if (response.candidates?.[0]?.groundingMetadata?.groundingChunks) {
          const chunks = response.candidates[0].groundingMetadata.groundingChunks;
          const uniqueSources = Array.from(new Set(chunks.map((chunk: any) => chunk.web?.uri).filter(u => u))) as string[];
          setSources(uniqueSources);
      }

      const summaryMarker = '[STYLE_DESCRIPTION_SECTION]';
      const summaryIndex = responseText.lastIndexOf(summaryMarker);

      if (summaryIndex !== -1) {
        setOutputBlocks([
          { title: "Generated Music Template", content: responseText.substring(0, summaryIndex).trim() },
          { title: "Style Description", content: responseText.substring(summaryIndex + summaryMarker.length).trim() },
        ]);
      } else {
        // Fallback if marker is missing: still display the text.
        setOutputBlocks([{ title: "Generated Music Template", content: responseText }]);
      }
    } catch (e) {
      setError("Failed to generate template. Quota reached or API error.");
    } finally {
      setLoading(false);
    }
  };

