// --- Optimized MultiSelect Component (Lazy Render & Search) ---
const MultiSelect = ({ label, options, selected, onChange, max = 5 }: { label: string, options: string[], selected: string[], onChange: (val: string[]) => void, max?: number }) => {
  const [filter, setFilter] = useState("");
  const [showAll, setShowAll] = useState(false);

  const toggle = (opt: string) => {
    if (selected.includes(opt)) {
      onChange(selected.filter(s => s !== opt));
    } else {
      if (selected.length < max) {
        onChange([...selected, opt]);
      }
    }
  };

  const filteredOptions = options.filter(opt => opt.toLowerCase().includes(filter.toLowerCase()));
  // Performance hack: Only render top 20 items initially to prevent mobile DOM freeze
  const visibleOptions = showAll || filter.length > 0 ? filteredOptions : filteredOptions.slice(0, 20);
  const hiddenCount = filteredOptions.length - visibleOptions.length;

  return (
    <div className="form-group">
      <div className="label-row">
        <label>{label}</label>
        <span className="count-badge">{selected.length}/{max}</span>
      </div>

      {/* Search Input for filtering huge lists */}
      <input 
        type="text" 
        className="filter-input"
        placeholder={`Search ${label.split('(')[0].trim()}...`} 
        value={filter}
        onChange={(e) => setFilter(e.target.value)}
        style={{marginBottom: '0.8rem', fontSize: '0.9rem', padding: '0.6rem'}}
      />

      <div className="chip-grid">
        {visibleOptions.map(opt => (
          <button
            key={opt}
            className={`chip ${selected.includes(opt) ? 'selected' : ''}`}
            onClick={() => toggle(opt)}
          >
            {opt}
          </button>
        ))}
      </div>

      {!showAll && filter.length === 0 && hiddenCount > 0 && (
        <button className="btn-text" onClick={() => setShowAll(true)}>
          + Show {hiddenCount} more
        </button>
      )}
      {showAll && filter.length === 0 && (
         <button className="btn-text" onClick={() => setShowAll(false)}>
          Show less
        </button>
      )}
    </div>
  );
};

// --- Optimized Music Visualizer (Smooth Updates) ---
const MusicVisualizer = ({ tempo, moods, songTitle, artistRef }: { tempo: number, moods: string[], songTitle: string, artistRef: string }) => {
  const sketchRef = useRef<HTMLDivElement>(null);

  // Use Refs to pass data to p5 loop without re-triggering effects/re-creating canvas
  const paramsRef = useRef({ tempo, moods, songTitle, artistRef });

  useEffect(() => {
    paramsRef.current = { tempo, moods, songTitle, artistRef };
  }, [tempo, moods, songTitle, artistRef]);

  useEffect(() => {
    // 1. Safety Check: Ensure window exists (browser env)
    if (typeof window === 'undefined') return;

    // 2. Access p5 from window safely
    const p5 = (window as any).p5;

    // If p5 isn't loaded, don't crash. Just abort.
    if (!p5) {
      console.warn("p5.js not loaded yet. Visualizer disabled.");
      return;
    }

    let p5Instance: any = null;

    // 3. Define Sketch
    const sketch = (p: any) => {
      let particles: any[] = [];
      let beatSize = 1;
      let lastBeat = 0;

      class Particle {
        pos: any; vel: any; acc: any; maxSpeed: number; color: any;
        constructor() {
          this.pos = p.createVector(p.random(p.width), p.random(p.height));
          this.vel = p.createVector(p.random(-1, 1), p.random(-1, 1));
          this.acc = p.createVector(0, 0);
          this.maxSpeed = 2;
          this.color = p.color(255); // Init white
        }
        update() {
          this.vel.add(this.acc);
          this.vel.limit(this.maxSpeed);
          this.pos.add(this.vel);
          this.acc.mult(0);
        }
        edges() {
          if (this.pos.x > p.width) this.pos.x = 0;
          if (this.pos.x < 0) this.pos.x = p.width;
          if (this.pos.y > p.height) this.pos.y = 0;
          if (this.pos.y < 0) this.pos.y = p.height;
        }
        display() {
          p.noStroke();
          p.fill(this.color);
          p.ellipse(this.pos.x, this.pos.y, 4, 4);
        }
      }

      p.setup = () => {
        const container = sketchRef.current;
        if (container) {
          p.createCanvas(container.offsetWidth, 400).parent(container);
          for (let i = 0; i < 80; i++) particles.push(new Particle()); // Reduced particle count for performance
        }
      };

      p.draw = () => {
        // Read latest params from Ref
        const { tempo, moods, songTitle, artistRef } = paramsRef.current;

        const primaryMood = moods.length > 0 ? moods[0] : 'Default';
        const colors = MOOD_COLORS[primaryMood as keyof typeof MOOD_COLORS] || MOOD_COLORS.Default;
        const beatTime = (60 / Math.max(40, tempo)) * 1000;

        p.background(18, 18, 18, 50); // Fade effect

        // Text
        p.textAlign(p.CENTER, p.CENTER);
        p.fill(255, 255, 255, 100); 
        p.textSize(28);
        p.text(songTitle || 'Untitled Song', p.width / 2, p.height / 2 - 20);
        p.textSize(18);
        p.fill(255, 255, 255, 80);
        p.text(artistRef || 'Independent Artist', p.width / 2, p.height / 2 + 20);

        // Beat Logic
        const currentTime = p.millis();
        if (currentTime - lastBeat > beatTime) {
            lastBeat = currentTime;
            beatSize = 1.4;
        }
        beatSize = p.lerp(beatSize, 1, 0.1); 

        // Orb
        const orbSize = p.width / 4 * beatSize;
        const mainColor = p.color(colors[0]);
        mainColor.setAlpha(150);
        p.fill(mainColor);
        p.noStroke();
        p.ellipse(p.width / 2, p.height / 2, orbSize, orbSize);

        // Particles
        for (let particle of particles) {
          // Dynamic color update based on mood
          if(p.frameCount % 60 === 0) {
              particle.color = p.color(p.random(colors));
          }
          particle.update();
          particle.edges();
          particle.display();
        }
      };

      p.windowResized = () => {
          const container = sketchRef.current;
          if(container) p.resizeCanvas(container.offsetWidth, 400);
      };
    };

    // 4. Initialize p5 ONLY ONCE
    if (sketchRef.current) {
        // Cleanup old children just in case
        while (sketchRef.current.firstChild) {
            sketchRef.current.removeChild(sketchRef.current.firstChild);
        }
        try {
            p5Instance = new p5(sketch, sketchRef.current);
        } catch (e) {
            console.error("Failed to start visualizer:", e);
        }
    }

    // 5. Cleanup on unmount
    return () => {
      if (p5Instance) {
        try {
            p5Instance.remove();
        } catch(e) { /* ignore cleanup errors */ }
      }
    };
  }, []); // Empty dependency array = create once

  return <div ref={sketchRef} className="visualizer-canvas"></div>;
};

